python3 - <<'PY'
import yaml

with open('governance/check-registry.yaml') as f:
    reg = yaml.safe_load(f)
with open('governance/pipeline-contract.yaml') as f:
    contract = yaml.safe_load(f)

valid = set()
for stage in contract['stages']:
    sid = stage['id']
    for c in stage.get('criteria', []):
        valid.add(f"{sid}/{c['id']}")
for cs in contract.get('cross_stage', []):
    valid.add(f"cross_stage/{cs['id']}")

print("Total valid stage/criterion pairs:", len(valid))
print()

bad = []
def check_entry(e, where):
    basis = e.get('basis')
    if basis is None:
        return
    bases = basis if isinstance(basis, list) else [basis]
    for b in bases:
        if '/' in b:
            if b not in valid:
                bad.append((e.get('id'), b, where, e.get('level')))

for e in reg.get('checks', []):
    check_entry(e, 'checks')
for e in reg.get('quarantine', []):
    check_entry(e, 'quarantine')

print("=== BASIS REFS NOT FOUND IN pipeline-contract.yaml ===")
for b in bad:
    print(b)

# Also: which valid criteria have NO check referencing them (informational, ids with check: null are expected to be uncovered)
referenced = set()
for e in reg.get('checks', []) + reg.get('quarantine', []):
    basis = e.get('basis')
    if not basis: continue
    bases = basis if isinstance(basis, list) else [basis]
    for b in bases:
        referenced.add(b)

print()
print("=== CRITERIA IN CONTRACT WITH NO check: field AND NO registry basis referencing them (informational) ===")
for stage in contract['stages']:
    sid = stage['id']
    for c in stage.get('criteria', []):
        cid = f"{sid}/{c['id']}"
        has_check_field = c.get('check') is not None
        if not has_check_field and cid not in referenced:
            print(cid, "-> check field:", c.get('check'))
